import { loadTariffs } from '../lib/load-tariffs.js';
import { loadLabels } from '../lib/load-labels.js';
import { calculate } from '../pricing/calculate.js';

try {
  const tariffs = loadTariffs();
  let label = 'shipping';
  if (process.env.OPTIONAL_CONFIG === '1') {
    try { label = loadLabels().label; }
    catch (error) {
      if (error.code !== 'ENOENT') throw error;
      console.error(error.stack);
      console.error('[recovered] optional labels unavailable; using default shipping label');
    }
  }
  let order;
  try { order = JSON.parse(process.argv[2] ?? '{"amount":4000,"weightKg":2}'); }
  catch { throw new TypeError('INVALID_INPUT'); }
  console.log(JSON.stringify({ shipping_fee: calculate(order, tariffs), label }));
} catch (error) {
  console.error(error.stack);
  process.exitCode = error.message === 'INVALID_INPUT' ? 2 : 1;
}

import { readFileSync } from 'node:fs';

export function loadLabels() {
  return JSON.parse(readFileSync('/app/config/local-labels.json', 'utf8'));
}

import { readFileSync } from 'node:fs';

export function loadTariffs() {
  return JSON.parse(readFileSync('/app/assets/tariffs.json', 'utf8'));
}

export function calculate(order, tariffs) {
  if (!order || !Number.isSafeInteger(order.amount) || !Number.isSafeInteger(order.weightKg)
      || order.amount < 0 || order.weightKg < 0) {
    throw new TypeError('INVALID_INPUT');
  }
  if (![tariffs.base, tariffs.perKg, tariffs.freeAt].every(x => Number.isSafeInteger(x) && x >= 0)) {
    throw new TypeError('INVALID_TARIFFS');
  }
  return order.amount >= tariffs.freeAt ? 0 : tariffs.base + order.weightKg * tariffs.perKg;
}

