  catch { throw new TypeError('INVALID_TRANSACTIONS'); }
  console.log(JSON.stringify({ ...aggregate(transactions, policy), label }));
} catch (error) {
  console.error(error.stack);
  process.exitCode = error.message === 'INVALID_TRANSACTIONS' ? 2 : 1;
}

